@Retries.OnceTranslated
private void completeActiveCopies(String reason) throws IOException {
  LOG.debug("Waiting for {} active copies to complete: {}",
      activeCopies.size(), reason);
  waitForCompletion(activeCopies);
  activeCopies.clear();
}

